('smart-watch-pro', 'smart-watch-pro', 'Smart Watch Pro', 'Aerospace-Grade Titanium Lifestyle Watch', 'Smartwatches', 'Smarter Every Day. Stay connected. Keep moving.', 'Advanced 1.43\" AMOLED fitness & lifestyle smartwatch with crystal-clear Bluetooth calling, 24/7 health tracking, 14-day battery life, and durable titanium bezel.', 6990, 9990, 6990, 65, '1.43-inch AMOLED / Titanium Bezel', '/vittal/smart-watch-pro.png', '[\"/vittal/smart-watch-pro.png\", \"/vittal/smart-watch-pro-1.png\", \"/vittal/smart-watch-pro-2.png\"]', 'Titanium Silver', 'Aerospace Titanium & Sapphire Glass', 1, 4.7, 540, 'Trending'),
('everyday-tablet-11', 'everyday-tablet-11', 'Everyday Tablet 11', 'Immersive 2K Entertainment & Productivity Tablet', 'Tablets', 'Crisp 2K Display with Dolby Atmos Audio', '11-inch crisp 2K display tablet perfect for productivity, streaming, and creative work with quad stereo speakers and 8,000mAh battery.', 24990, 32990, 24990, 40, '11-inch 2K / 8GB / 128GB', '/vittal/everyday-tablet-11.png', '[\"/vittal/everyday-tablet-11.png\", \"/vittal/everyday-tablet-11-1.png\", \"/vittal/everyday-tablet-11-2.png\"]', 'Nordic Blue', 'Anodized Aluminum', 1, 4.8, 218, 'Best Seller'),
('wireless-earbuds', 'wireless-earbuds', 'Wireless Earbuds', 'Active Noise Cancellation (ANC) True Wireless', 'Headphones & Earbuds', 'Feel Every Beat. Your world. Better sound.', 'Hybrid 42dB Active Noise Cancellation (ANC), 36-hour total playback, high-definition 11mm dynamic drivers, and IPX5 sweat resistance.', 2999, 3999, 2999, 120, '36h Playback / Hybrid ANC', '/vittal/wireless-earbuds.png', '[\"/vittal/wireless-earbuds.png\", \"/vittal/wireless-earbuds-1.png\", \"/vittal/wireless-earbuds-2.png\"]', 'Gloss White', 'Polycarbonate with Matte Case', 1, 4.6, 890, 'Deal'),
('portable-bluetooth-speaker', 'portable-bluetooth-speaker', 'Portable Bluetooth Speaker', '360° Heavy Bass Waterproof Speaker', 'Speakers', 'Immersive 360° Sound with 20h Playback', 'Rugged IP67 waterproof outdoor speaker delivering 24W 360-degree punchy bass, 20 hours battery life, and dual TWS wireless pairing.', 3999, 4999, 3999, 80, '24W Output / IP67 Waterproof', '/vittal/portable-bluetooth-speaker.png', '[\"/vittal/portable-bluetooth-speaker.png\", \"/vittal/portable-bluetooth-speaker-1.png\"]', 'Midnight Black', 'Silicon & Fabric Mesh', 1, 4.7, 412, 'Popular'),
('compact-power-bank', 'compact-power-bank', 'Compact Power Bank 10000mAh', '22.5W Fast Charging Ultra-Slim Power Bank', 'Smart Gadgets', 'High-Density Fast Power On The Go', 'Pocket-sized 10,000mAh power bank featuring 22.5W USB-C Power Delivery, QuickCharge 3.0, and high-contrast digital LED percentage display.', 1499, 1999, 1499, 150, '10,000mAh / 22.5W PD', '/vittal/compact-power-bank.png', '[\"/vittal/compact-power-bank.png\"]', 'Deep Navy', 'Fireproof ABS Shell', 1, 4.7, 630, 'Deal');
